(function(){
  const admin=location.hash==='#coordenacao';
  const login=document.getElementById(admin?'adminLoginView':'loginView');
  login?.classList.remove('hidden');
  const message=login?.querySelector('.message');if(message)message.textContent='Carregando Firebase...';
  document.querySelectorAll('#adminLoginForm button,#profLoginForm button').forEach(button=>button.disabled=true);
  function enableForms(){document.querySelectorAll('#adminLoginForm button,#profLoginForm button').forEach(button=>button.disabled=false);}
  window.MaximusFirebaseLoadFailure=function(){
    document.querySelectorAll('#adminLoginForm button,#profLoginForm button').forEach(button=>button.disabled=true);
    ['loginView','adminLoginView'].forEach(id=>document.getElementById(id)?.classList.add('hidden'));
    const view=document.getElementById(location.hash==='#coordenacao'?'adminLoginView':'loginView');view?.classList.remove('hidden');
    const text=view?.querySelector('.message');if(text){text.textContent='Não foi possível carregar o Firebase. Verifique sua conexão e o acesso a www.gstatic.com, e recarregue a página.';text.className='message error';const retry=document.createElement('button');retry.type='button';retry.className='btn light';retry.textContent='Tentar novamente';retry.addEventListener('click',()=>location.reload());text.after(retry);}
    document.querySelectorAll('[data-access-page]').forEach(link=>link.addEventListener('click',()=>location.reload()));
  };
  window.MaximusFirebaseReady=(async()=>{
    if(!window.firebase){
      for(const name of ['app','auth','database']){
        await new Promise((resolve,reject)=>{
          const script=document.createElement('script');let timeout;
          const finish=error=>{clearTimeout(timeout);script.onload=script.onerror=null;if(error){script.remove();reject(error);}else resolve();};
          script.src='https://www.gstatic.com/firebasejs/12.19.0/firebase-'+name+'-compat.js';
          script.onload=()=>finish();script.onerror=()=>finish(new Error('Firebase indisponível'));
          timeout=setTimeout(()=>finish(new Error('Tempo de conexão excedido')),15000);document.head.append(script);
        });
      }
      if(window.firebase?.SDK_VERSION!=='12.19.0')throw new Error('Versão inesperada do Firebase');
    }
    enableForms();if(message)message.textContent='';
  })();
  window.MaximusFirebaseReady.catch(()=>{});
})();

