  function sanitizePastedHtml(html){
    const temp=document.createElement('div');
    temp.innerHTML=html;
    temp.querySelectorAll('script,style,iframe,object,embed,link,meta,base,title,svg,math,form,input,button,video,audio,template,frame,frameset,applet').forEach(el=>el.remove());
    temp.querySelectorAll('*').forEach(el=>{
      [...el.attributes].forEach(attr=>{
        const name=attr.name.toLowerCase();
        if(name.startsWith('on')||['id','name','srcset','srcdoc','formaction','action','contenteditable'].includes(name)) el.removeAttribute(attr.name);
        if(name==='href'&&!/^(https?:|mailto:)/i.test(attr.value))el.removeAttribute('href');
        if(name==='src' && el.tagName==='IMG' && !/^(data:image\/(?:png|jpeg|jpg|gif|webp);base64,|https?:\/\/)/i.test(attr.value)) el.removeAttribute(attr.name);
        if(name==='style'){
          const safe = attr.value
            .split(';')
            .map(x=>x.trim())
            .filter(x=>/^(text-align|font-weight|font-style|text-decoration|font-size|width|height|display|margin|max-width|object-fit)\s*:/i.test(x)&&!/(?:url|expression|@import|javascript)\s*[:(]/i.test(x))
            .join('; ');
          if(safe) el.setAttribute('style', safe); else el.removeAttribute('style');
        }
      });
    });
    return temp.innerHTML;
  }

  function setEditorContent(content){
    const editor=$('questoesEditor');
    const hidden=$('questoesTexto');
    const safe=sanitizePastedHtml(content||'');
    if(editor) editor.innerHTML = safe;
    if(hidden) hidden.value = safe;
    invalidatePreview();
    generatedAnswerKey={}; answerKeyContent='';
    if($('answerKeys'))$('answerKeys').replaceChildren();
  }

  function getEditorContent(){
    const editor=$('questoesEditor');
    const hidden=$('questoesTexto');
    if(editor){
      hidden.value = editor.innerHTML.trim();
      return hidden.value;
    }
    return hidden?.value || '';
  }

  function editorContentToPlainText(html){
    const tmp=document.createElement('div');
    tmp.innerHTML=html || '';
    tmp.querySelectorAll('br').forEach(br=>br.replaceWith('\n'));
    tmp.querySelectorAll('p,div,li,h1,h2,h3,h4,tr').forEach(el=>{ el.appendChild(document.createTextNode('\n')); });
    return tmp.textContent.replace(/\u00a0/g,' ').replace(/\n{3,}/g,'\n\n').trim();
  }

  function renderFreeContentQuestion(html){
    const temp=document.createElement('div');
    temp.innerHTML = sanitizePastedHtml(html || '');
    if(!temp.textContent.trim()&&!temp.querySelector('img,table')) return '';
    return `<article class="question free-content">${temp.innerHTML}</article>`;
  }


  function setupDropdownMenus(){
    document.querySelectorAll('.sidebar nav a').forEach(link=>{
      link.addEventListener('click', ()=>{
        const href = link.getAttribute('href');
        document.querySelectorAll('.sidebar nav a').forEach(a=>a.classList.remove('active'));
        link.classList.add('active');
      });
    });
  }

  function setupHamburgerMenus(){
    [
      {btn:'adminHamburger', backdrop:'adminMenuBackdrop'},
      {btn:'profHamburger', backdrop:'profMenuBackdrop'}
    ].forEach(cfg=>{
      const btn=$(cfg.btn);
      const backdrop=$(cfg.backdrop);
      if(!btn) return;

      const appView = btn.closest('.app');
      const sidebar = appView?.querySelector('.sidebar');
      if(!appView || !sidebar) return;

      const closeMenu = ()=>setHamburgerMenu(appView, sidebar, backdrop, btn, false);
      const toggleMenu = ()=>setHamburgerMenu(appView, sidebar, backdrop, btn, !sidebar.classList.contains('menu-open'));

      closeMenu();
      btn.addEventListener('click', toggleMenu);
      backdrop?.addEventListener('click', closeMenu);

      sidebar.querySelectorAll('nav a').forEach(link=>{
        link.addEventListener('click', ()=>{
          sidebar.querySelectorAll('nav a').forEach(a=>a.classList.remove('active'));
          link.classList.add('active');
          closeMenu();
        });
      });

      document.addEventListener('keydown', e=>{ if(e.key==='Escape') closeMenu(); });
      window.addEventListener('resize', closeMenu);
    });
  }

  function setHamburgerMenu(appView, sidebar, backdrop, btn, open){
    if(!sidebar) return;
    sidebar.classList.toggle('menu-open', !!open);
    appView?.classList.toggle('menu-open', !!open);
    backdrop?.classList.toggle('hidden', !open);
    btn?.setAttribute('aria-expanded', open?'true':'false');
  }

  function closeHamburgerMenu(appView){
    const sidebar=appView?.querySelector('.sidebar');
    const backdrop=appView?.querySelector('.menu-backdrop');
    const btn=appView?.querySelector('.hamburger-btn');
    setHamburgerMenu(appView, sidebar, backdrop, btn, false);
  }


