  async function cadastrarAlunoManualLegacy(e){
    e.preventDefault();
    const submitBtn = e.submitter || $('alunoManualForm')?.querySelector('button[type="submit"]');
    setMsg('alunoManualMsg','Salvando aluno...');
    try{
      await withBusyState(submitBtn,'Salvando aluno...', async()=>{
        const nome = norm($('manualAlunoNome')?.value);
        const turma = norm($('manualAlunoTurma')?.value);
        if(!nome) throw new Error('Informe o nome do aluno.');
        if(!turma) throw new Error('Informe a turma do aluno.');
        const main = {
          nome,
          turma,
          numero: norm($('manualAlunoNumero')?.value),
          diagnostico: norm($('manualAlunoDiagnostico')?.value),
          adaptacao: norm($('manualAlunoAdaptacao')?.value),
          tipoProva: norm($('manualAlunoTipoProva')?.value),
          orientacoes: norm($('manualAlunoOrientacoes')?.value),
          turmaKey:C.classKey(turma),
          matricula:norm($('manualAlunoMatricula')?.value),
          abaOrigem: 'Cadastro manual',
          dadosCompletos: {}
        };
        main.dadosCompletos = {
          'Nome do aluno': main.nome,
          'Turma': main.turma,
          'Número': main.numero,
          'Diagnóstico/laudo': main.diagnostico,
          'Adaptação': main.adaptacao,
          'Tipo de prova': main.tipoProva,
          'Orientações': main.orientacoes,
          'Origem': 'Cadastro manual'
        };
        const key = makeAlunoKey(main, new Set(alunosCache.map(a=>a.id)));
        await db.ref('alunos/'+key).set({
          ...main,
          criadoEm: nowIso(),
          atualizadoEm: nowIso(),
          origemCadastro: 'manual'
        });
        await audit('cadastro_manual_aluno', {alunoId:key, nome, turma});
      });
      $('alunoManualForm')?.reset();
      setMsg('alunoManualMsg','Aluno cadastrado manualmente com sucesso.','ok');
    }catch(error){
      setMsg('alunoManualMsg', firebaseError(error), 'error');
    }
  }

