  async function cadastrarProfessorLegacy(e){
    e.preventDefault();
    const submitBtn = e.submitter || $('professorForm')?.querySelector('button[type="submit"]');
    setMsg('professorMsg','Cadastrando professor...');
    try{
      await withBusyState(submitBtn,'Cadastrando professor...', async()=>{
        const senha=requireSamePassword('cadProfSenha','cadProfConfirmaSenha');
        const turmasMarcadas=Array.from(document.querySelectorAll('#turmasCheckboxes input:checked')).map(i=>i.value);
        const turmasExtras=splitTurmas($('cadProfTurmasExtras')?.value);
        const turmas=Array.from(new Set([...turmasMarcadas, ...turmasExtras].map(norm).filter(Boolean)));
        if(!turmas.length) throw new Error('Selecione ou digite pelo menos uma turma para o professor.');
        const sAuth=await getSecondaryAuth();
        const cred=await sAuth.createUserWithEmailAndPassword(norm($('cadProfEmail').value), senha);
        await db.ref('usuarios/'+cred.user.uid).set({role:'professor', nome:norm($('cadProfNome').value), email:norm($('cadProfEmail').value), turmas, turmasAcesso:Object.fromEntries(turmas.map(t=>[C.classKey(t),true])), criadoEm:nowIso(), ativo:true});
        await sAuth.signOut();
        await audit('cadastro_professor',{email:norm($('cadProfEmail').value), turmas});
      });
      setMsg('professorMsg','Professor cadastrado com sucesso e vinculado às turmas.','ok');
      $('professorForm').reset();
    }
    catch(error){ setMsg('professorMsg', firebaseError(error),'error'); }
  }

  function makeAlunoKey(main, seenKeys){
    const raw = `${main.nome || 'aluno'}_${main.turma || main.abaOrigem || 'sem_turma'}_${main.numero || main.__linha || ''}`;
    let base = lower(raw).replace(/[^a-z0-9]+/g,'_').replace(/^_+|_+$/g,'').slice(0,110) || uid();
    let key = base;
    let n = 2;
    while(seenKeys.has(key)){
      key = `${base}_${n++}`;
    }
    seenKeys.add(key);
    return key;
  }

  async function firebaseBatchUpdate(updates, batchSize){
    const entries = Object.entries(updates);
    for(let i=0;i<entries.length;i+=batchSize){
      const batch = Object.fromEntries(entries.slice(i, i+batchSize));
      await db.ref().update(batch);
    }
  }

  async function importarPlanilhaAlunos(file){
    const report=$('importReport'),actor=currentUser?.uid;
    try {
      requireCoordinator();report.textContent='Identificando as abas, turmas e alunos...';
      await window.MaximusImporter.open(file,{
        existing:()=>alunosCache,
        classes:()=>activeClassList().map(t=>t.nome),
        confirm:async(plan,meta)=>exclusiveClassChange(async()=>{
          requireCoordinator();if(currentUser.uid!==actor)throw new Error('A sessão mudou. Analise a planilha novamente.');
          const latest=await managementSnapshot(),fresh=C.importPlan(plan.incoming,latest.students,false);
          if(fresh.errors.length)throw new Error(fresh.errors.join('\n'));
          if(fresh.added!==plan.added||fresh.changed!==plan.changed||fresh.unchanged!==plan.unchanged)throw new Error('A base mudou durante a conferência. Feche e analise a planilha novamente para atualizar os totais.');
          const revision=uid(),at=nowIso(),updates={...fresh.updates};
          appendClassRegistration(updates,plan.classes,latest.registry);
          updates['configuracao/importacoes/'+revision]={...meta,por:actor,em:at,turmas:plan.classes.length,novos:fresh.added,atualizados:fresh.changed,inalterados:fresh.unchanged,mapeamentos:plan.schemas};
          updates['configuracao/ultimaImportacao']={id:revision,em:at,arquivo:meta.arquivo,total:fresh.records.length,turmas:plan.classes.length};
          await sendManagementUpdates(updates);
          report.textContent=`Importação concluída: ${plan.classes.length} turma(s), ${fresh.added} novo(s) aluno(s), ${fresh.changed} atualizado(s) e ${fresh.unchanged} sem alteração. Os professores recebem a atualização automaticamente.`;
          setMsg('turmaMsg',report.textContent,'ok');
        })
      });
    } catch(e) {report.textContent='Não foi possível analisar a planilha: '+firebaseError(e);setMsg('turmaMsg',report.textContent,'error');}
  }

  async function importarPlanilhaProfessoresLegacy(){
    const file=$('arquivoProfessores')?.files?.[0]; if(!file){ $('profImportReport').textContent='Selecione a planilha de professores.'; return; }
    $('profImportReport').textContent='Importando professores...';
    try{ const wb=await readWorkbook(file); const sAuth=await getSecondaryAuth(); let total=0, erros=[];
      for(const sheetName of wb.SheetNames){ const parsed=firstNonEmptyRowsToObjects(wb.Sheets[sheetName], sheetName); const hNome=inferField(parsed.headers,['nome','professor','nome do professor']); const hEmail=inferField(parsed.headers,['email','e-mail','mail']); const hSenha=inferField(parsed.headers,['senha','password']); const hTurmas=inferField(parsed.headers,['turmas','turma','series','séries']); for(const row of parsed.rows){ const nome=norm(row[hNome]); const email=norm(row[hEmail]); const senha=norm(row[hSenha]); const turmas=splitTurmas(row[hTurmas]); if(!email || !senha || senha.length<6) continue; try{ const cred=await sAuth.createUserWithEmailAndPassword(email,senha); await db.ref('usuarios/'+cred.user.uid).set({role:'professor', nome:nome||email, email, turmas, turmasAcesso:Object.fromEntries(turmas.map(t=>[C.classKey(t),true])), criadoEm:nowIso(), ativo:true}); total++; }catch(e){ erros.push(`${email}: ${firebaseError(e)}`); } } }
      await sAuth.signOut(); await audit('importar_professores',{arquivo:file.name,total}); $('profImportReport').textContent=`Professores importados: ${total}`+(erros.length?`\nErros:\n${erros.join('\n')}`:'');
    }catch(error){ $('profImportReport').textContent='Erro: '+firebaseError(error); }
  }

  function openEditAluno(id){ const a=alunosCache.find(x=>x.id===id); if(!a)return; editAlunoId=id; const fields=$('editFields'); const data={...(a.dadosCompletos||{}), nome:a.nome||'', turma:a.turma||'', numero:a.numero||'', diagnostico:a.diagnostico||'', adaptacao:a.adaptacao||'', tipoProva:a.tipoProva||'', orientacoes:a.orientacoes||'', complementoProfessor:a.complementoProfessor||''}; const keys=Array.from(new Set(['nome','turma','numero','diagnostico','adaptacao','tipoProva','orientacoes','complementoProfessor',...Object.keys(data)])); fields.innerHTML=keys.map(k=>`<label>${escapeHtml(k)}<textarea data-edit-field="${escapeHtml(k)}" rows="2">${escapeHtml(data[k])}</textarea></label>`).join(''); $('editModal').classList.remove('hidden'); setMsg('editMsg',''); }
  async function salvarEdicaoAlunoLegacy(){ if(!editAlunoId)return; const obj={}, dadosCompletos={}; document.querySelectorAll('[data-edit-field]').forEach(el=>{ const k=el.dataset.editField, v=norm(el.value); dadosCompletos[k]=v; obj[k]=v; }); obj.turmaKey=C.classKey(obj.turma); obj.dadosCompletos=Object.fromEntries(Object.entries(dadosCompletos).map(([k,v])=>[C.safeKey(k),v])); obj.atualizadoEm=nowIso(); await db.ref('alunos/'+editAlunoId).update(obj); await audit('editar_aluno',{id:editAlunoId}); setMsg('editMsg','Alterações salvas com sucesso.','ok'); }
  async function excluirAlunoAtual(){ if(!editAlunoId || !confirm('Excluir este aluno?'))return; await db.ref('alunos/'+editAlunoId).remove(); await audit('excluir_aluno',{id:editAlunoId}); $('editModal').classList.add('hidden'); }
  function exportBackup(){ const data={geradoEm:nowIso(),regras:ruleConfigCache, alunos:alunosCache, professores:professoresCache, turmas:turmasCache, colunas:colunasCache}; downloadText('backup_escola_maximus.json', JSON.stringify(data,null,2)); }
  async function resetSistema(){ if(!confirm('Zerar alunos e auditoria do sistema? Professores e coordenação serão mantidos.'))return; const updates=Object.fromEntries(alunosCache.map(a=>['alunos/'+a.id,null]));await db.ref().update(updates);await db.ref('auditoria').remove(); await audit('reset_sistema',{}); }

  function setupDocumentImport(){
    const zone=$('documentDropZone'), input=$('documentUpload');
    if(!zone || !input) return;
    const choose=()=>input.click();
    zone.addEventListener('click',choose);
    zone.addEventListener('keydown',e=>{ if(e.key==='Enter'||e.key===' '){ e.preventDefault(); choose(); }});
    ['dragenter','dragover'].forEach(ev=>zone.addEventListener(ev,e=>{ e.preventDefault(); zone.classList.add('dragging'); }));
    ['dragleave','drop'].forEach(ev=>zone.addEventListener(ev,e=>{ e.preventDefault(); zone.classList.remove('dragging'); }));
    zone.addEventListener('drop',e=>{ const file=e.dataTransfer?.files?.[0]; if(file) processarDocumentoImportado(file); });
    input.addEventListener('change',e=>{ const file=e.target.files?.[0]; if(file) processarDocumentoImportado(file); input.value=''; });
    $('usarDocumentoNoConteudo')?.addEventListener('click',()=>{ if(documentoImportado?.text){ $('conteudoMinistrado').value=documentoImportado.text; setMsg('profMsg','Conteúdo do documento carregado para a IA local.','ok'); }});
    $('usarDocumentoNoEditor')?.addEventListener('click',()=>{ if(!documentoImportado)return; const html=documentoImportado.html||`<div class="imported-document">${escapeHtml(documentoImportado.text).replace(/\n/g,'<br>')}</div>`; setEditorContent(`${getEditorContent()}${html}`); setMsg('profMsg','Documento inserido no editor. Revise a formatação antes de gerar o PDF.','ok'); });
    $('removerDocumento')?.addEventListener('click',limparDocumentoImportado);
  }

  async function processarDocumentoImportado(file){
    const status=$('documentImportStatus');
    limparDocumentoImportado();status.textContent=`Lendo ${file.name}...`;
    try{
      if(file.size>20*1024*1024) throw new Error('O arquivo deve ter no máximo 20 MB.');
      const ext=(file.name.split('.').pop()||'').toLowerCase();
      let text='', html='';
      if(file.type.startsWith('image/')){
        const data=await optimizeImageDataUrl(await fileToDataUrl(file),1400,.86);
        html=`<figure class="editor-image-wrap"><img src="${data}" alt="${escapeHtml(file.name)}" style="width:70%;height:auto;display:block;margin:12px auto"><figcaption>${escapeHtml(file.name)}</figcaption></figure>`;
      }else if(ext==='docx'){
        if(!window.mammoth) throw new Error('Leitor de DOCX não carregado. Verifique a internet.');
        const result=await window.mammoth.convertToHtml({arrayBuffer:await file.arrayBuffer()});
        html=sanitizePastedHtml(result.value); text=editorContentToPlainText(html);
      }else if(ext==='pdf'){
        if(!window.pdfjsLib) throw new Error('Leitor de PDF não carregado. Verifique a internet.');
        window.pdfjsLib.GlobalWorkerOptions.workerSrc=window.MaximusAssets.pdfWorkerURL();
        const pdf=await window.pdfjsLib.getDocument({data:new Uint8Array(await file.arrayBuffer())}).promise;
        const pages=[];
        if(pdf.numPages>100){await pdf.destroy();throw new Error('Use PDFs de até 100 páginas por importação.');}
        for(let i=1;i<=pdf.numPages;i++){ const p=await pdf.getPage(i); const c=await p.getTextContent(); pages.push(c.items.map(x=>x.str).join(' ')); }
        text=pages.join('\n\n');await pdf.destroy();if(!text.trim())throw new Error('Este PDF não contém texto selecionável. Use um DOCX ou cole o texto; PDFs digitalizados precisam de OCR.'); html=`<div class="imported-document">${escapeHtml(text).replace(/\n/g,'<br>')}</div>`;
      }else if(['txt','html','htm'].includes(ext)){
        text=await file.text(); html=ext==='txt'?`<div class="imported-document">${escapeHtml(text).replace(/\n/g,'<br>')}</div>`:sanitizePastedHtml(text); if(ext!=='txt') text=editorContentToPlainText(html);
      }else throw new Error('Formato não aceito. Use PDF, DOCX, TXT, HTML ou imagem.');
      documentoImportado={name:file.name,text,html};
      status.textContent=`Arquivo pronto: ${file.name}${text?` • ${text.length} caracteres extraídos`:''}${ext==='pdf'?' · Apenas texto; para preservar imagens, importe DOCX ou envie as imagens separadamente.':''}`;
      $('usarDocumentoNoConteudo')?.classList.toggle('hidden',!text);
      $('usarDocumentoNoEditor')?.classList.remove('hidden');
      $('removerDocumento')?.classList.remove('hidden');
    }catch(error){ documentoImportado=null; status.textContent=`Erro: ${firebaseError(error)}`; }
  }

  function fileToDataUrl(file){ return new Promise((resolve,reject)=>{ const r=new FileReader(); r.onload=()=>resolve(r.result); r.onerror=reject; r.readAsDataURL(file); }); }
  function limparDocumentoImportado(){ documentoImportado=null; if($('documentImportStatus')) $('documentImportStatus').textContent=''; ['usarDocumentoNoConteudo','usarDocumentoNoEditor','removerDocumento'].forEach(id=>$(id)?.classList.add('hidden')); }

  function setupDocumentOptions(){
    $('tipoDocumento')?.addEventListener('change',e=>$('tipoDocumentoPersonalizadoBox')?.classList.toggle('hidden',e.target.value!=='personalizado'));
    $('disciplina')?.addEventListener('input',()=>renderSugestoesPedagogicas(alunoSelecionado));
    $('formatoQuestoes')?.addEventListener('change',atualizarControlesFormato);
    $('qtdObjetivas')?.addEventListener('input',sincronizarTotalMisto);
    $('qtdDiscursivas')?.addEventListener('input',sincronizarTotalMisto);
    atualizarControlesFormato();
  }

  function atualizarControlesFormato(){
    const formato=$('formatoQuestoes')?.value||'misto';
    $('qtdObjetivasBox')?.classList.toggle('hidden',formato!=='misto');
    $('qtdDiscursivasBox')?.classList.toggle('hidden',formato!=='misto');
    $('qtdQuestoesBox')?.classList.toggle('hidden',formato==='misto');
    if(formato==='misto') sincronizarTotalMisto();
  }

  function sincronizarTotalMisto(){
    const objetivas=Math.max(0,Math.min(25,parseInt($('qtdObjetivas')?.value||'0',10)||0));
    const discursivas=Math.max(0,Math.min(25,parseInt($('qtdDiscursivas')?.value||'0',10)||0));
    if($('qtdQuestoes')) $('qtdQuestoes').value=Math.min(25,objetivas+discursivas);
  }

  function getDocumentType(){ const selected=norm($('tipoDocumento')?.value)||'AVALIAÇÃO'; return selected==='personalizado'?(norm($('tipoDocumentoPersonalizado')?.value)||'DOCUMENTO'):selected; }

  function renderSugestoesPedagogicas(aluno){
    const box=$('sugestoesPedagogicasBox'); if(!box)return;
    const disciplina=lower($('disciplina')?.value||'');
    const gerais=['Apresente um comando por vez e confirme a compreensão.','Permita tempo de organização antes da resposta.'];
    let area=[];
    if(/mat|fis|quim/.test(disciplina)) area=['Destaque dados, unidades e fórmulas antes do cálculo.','Divida situações-problema em etapas numeradas.'];
    else if(/port|liter|reda|ingl/.test(disciplina)) area=['Antecipe o vocabulário essencial do texto.','Permita marcações e releitura do texto-base.'];
    else if(/hist|geo|socio|filo/.test(disciplina)) area=['Use linha do tempo, mapa mental ou comparação visual.','Relacione conceitos abstratos a exemplos do cotidiano.'];
    else if(/bio|cien/.test(disciplina)) area=['Use esquemas, imagens legendadas e relações de causa e efeito.','Retome os conceitos essenciais antes da aplicação.'];
    else area=['Associe o conteúdo a um exemplo concreto.','Use recursos visuais quando ajudarem na compreensão.'];
    const adapt=detectAdaptations(aluno||{}).filter(r=>!['nome','qr'].includes(r.id)).slice(0,3).map(r=>r.what);
    box.innerHTML=[...new Set([...area,...gerais,...adapt])].map((s,i)=>`<div class="card-mini active"><strong>Sugestão ${i+1}</strong><p>${escapeHtml(s)}</p></div>`).join('');
  }

  function setupQuestionBank(){
    $('salvarBancoQuestoes')?.addEventListener('click',async()=>{try{await withBusyState($('salvarBancoQuestoes'),'Salvando questões...',salvarNoBancoQuestoes);}catch(e){setMsg('profMsg',firebaseError(e),'error');}});
    $('buscaBancoQuestoes')?.addEventListener('input',renderBancoQuestoes);
    $('filtroBancoDisciplina')?.addEventListener('input',renderBancoQuestoes);
  }

  async function salvarNoBancoQuestoes(){
    const conteudo=getEditorContent();
    if(!norm(editorContentToPlainText(conteudo))){ setMsg('profMsg','Crie ou cole questões no editor antes de salvar.','error'); return; }
    if(new Blob([conteudo]).size>4*1024*1024){ setMsg('profMsg','O conteúdo está muito grande para o banco. Reduza o tamanho ou a quantidade de imagens.','error'); return; }
    const key=uid();
    await db.ref(`bancoQuestoes/${currentUser.uid}/${key}`).set({disciplina:norm($('disciplina')?.value),tema:norm($('temaConteudo')?.value),dificuldade:norm($('dificuldade')?.value),conteudo,criadoEm:nowIso()});
    await audit('salvar_banco_questoes',{id:key});
    setMsg('profMsg','Questões salvas no seu banco.','ok');
  }

  function renderBancoQuestoes(){
    const box=$('bancoQuestoesLista'); if(!box)return;
    const busca=lower($('buscaBancoQuestoes')?.value||''), disc=lower($('filtroBancoDisciplina')?.value||'');
    const list=bancoQuestoesCache.filter(q=>(!disc||lower(q.disciplina).includes(disc))&&(!busca||lower(`${q.disciplina} ${q.tema} ${editorContentToPlainText(q.conteudo)}`).includes(busca)));
    box.innerHTML=list.map(q=>`<article class="question-bank-item"><div><strong>${escapeHtml(q.tema||'Questões sem título')}</strong><span>${escapeHtml(q.disciplina||'Sem disciplina')} • ${escapeHtml(q.dificuldade||'')}</span><p>${escapeHtml(editorContentToPlainText(q.conteudo).slice(0,180))}</p></div><div class="actions"><button class="btn secondary" data-bank-use="${q.id}" type="button">Usar no editor</button><button class="btn danger" data-bank-delete="${q.id}" type="button">Excluir</button></div></article>`).join('')||'<p class="muted">Nenhuma questão encontrada.</p>';
    box.querySelectorAll('[data-bank-use]').forEach(btn=>btn.addEventListener('click',()=>{ const q=bancoQuestoesCache.find(x=>x.id===btn.dataset.bankUse); if(q){ setEditorContent(q.conteudo); if(q.disciplina)$('disciplina').value=q.disciplina; if(q.tema)$('temaConteudo').value=q.tema; setMsg('profMsg','Questões carregadas no editor.','ok'); }}));
    box.querySelectorAll('[data-bank-delete]').forEach(btn=>btn.addEventListener('click',async()=>{ if(confirm('Excluir estas questões do seu banco?')) await db.ref(`bancoQuestoes/${currentUser.uid}/${btn.dataset.bankDelete}`).remove(); }));
  }

