  function showProfLogin(){ showAccess('professor'); }
  function showProfApp(){ showWorkspace('professor'); }
  function startProfessorRealtime(){
    if(listenersStarted)detachListeners();listenersStarted=true;
    startSharedConfig();
    const allowed=Array.isArray(currentProfile.turmas)?currentProfile.turmas:[],byClass=new Map();
    allowed.forEach(t=>{
      const key=C.classKey(t),ref=db.ref('alunos').orderByChild('turmaKey').equalTo(key);studentRefs.push(ref);
      ref.on('value',snap=>{byClass.set(key,Object.entries(snap.val()||{}).map(([id,a])=>({id,...a})));alunosCache=Array.from(byClass.values()).flat();refreshDerivedCaches();initProfessorWorkspace();invalidatePreview('A base de alunos foi atualizada.');},err=>{byClass.delete(key);alunosCache=Array.from(byClass.values()).flat();refreshDerivedCaches();initProfessorWorkspace();setMsg('profMsg','Não foi possível carregar a turma. Procure a coordenação para revisar seu acesso.','error');});
    });
    db.ref(`bancoQuestoes/${currentUser.uid}`).on('value',snap=>{bancoQuestoesCache=Object.entries(snap.val()||{}).map(([id,q])=>({id,...q})).sort((a,b)=>String(b.criadoEm||'').localeCompare(String(a.criadoEm||'')));renderBancoQuestoes();});
    initProfessorWorkspace();
  }

  function initProfessorWorkspace(){ const turmas=Array.isArray(currentProfile.turmas)?currentProfile.turmas:[]; $('profResumo').textContent=`${currentProfile.nome || currentProfile.email} • ${turmas.length} turma(s) vinculada(s) • tempo real`; const sel=$('profTurmaSelect'); const old=sel.value; sel.innerHTML=turmas.length?turmas.map(t=>`<option value="${escapeHtml(t)}">${escapeHtml(t)}</option>`).join(''):'<option value="">Nenhuma turma vinculada</option>'; if(old && turmas.includes(old)) sel.value=old; if($('dataDocumento') && !$('dataDocumento').value) $('dataDocumento').value=today(); renderAlunosProfessor(); }
  function renderAlunosProfessor(){ const turma=$('profTurmaSelect')?.value; const alunos=alunosCache.filter(a=>C.classKey(a.turma)===C.classKey(turma)).sort((a,b)=>norm(a.nome).localeCompare(norm(b.nome),'pt-BR')); const old=$('profAlunoSelect')?.value; $('profAlunoSelect').innerHTML=alunos.length?alunos.map(a=>`<option value="${a.id}">${escapeHtml(a.nome)}</option>`).join(''):'<option value="">Nenhum aluno nesta turma</option>'; if(old && alunos.some(a=>a.id===old)) $('profAlunoSelect').value=old; updateAlunoSelecionado(); }
  function updateAlunoSelecionado(){ invalidatePreview(); alunoSelecionado=alunosCache.find(a=>a.id===$('profAlunoSelect')?.value)||null; const box=$('alunoInfo'); if(!alunoSelecionado){ $('adaptRulesBox')?.replaceChildren(); box.innerHTML='<p class="muted">Selecione um aluno.</p>'; renderSugestoesPedagogicas(null); return; } $('complementoProfessor').value=alunoSelecionado.complementoProfessor||''; const rules=detectAdaptations(alunoSelecionado); box.innerHTML=`<p><strong>Aluno:</strong> ${escapeHtml(alunoSelecionado.nome)}</p><p><strong>Turma:</strong> ${escapeHtml(alunoSelecionado.turma)} ${alunoSelecionado.numero?`• <strong>Nº:</strong> ${escapeHtml(alunoSelecionado.numero)}`:''}</p><p><strong>Diagnóstico/laudo:</strong> ${escapeHtml(alunoSelecionado.diagnostico||'Não informado')}</p><p><strong>Orientações da planilha:</strong> ${escapeHtml(alunoSelecionado.orientacoes||alunoSelecionado.adaptacao||'Não informado')}</p><p><strong>Adaptações detectadas:</strong> ${escapeHtml(rules.map(r=>r.title).join('; ') || 'Adaptação básica')}</p>`; renderActiveAdaptations(rules); renderSugestoesPedagogicas(alunoSelecionado); }

  async function salvarComplementoProfessor(){ if(!alunoSelecionado){ setMsg('profMsg','Selecione um aluno.','error'); return; } try{ await db.ref('alunos/'+alunoSelecionado.id+'/complementoProfessor').set(norm($('complementoProfessor').value)); await audit('salvar_complemento_professor',{alunoId:alunoSelecionado.id}); setMsg('profMsg','Complemento salvo com sucesso.','ok'); }catch(error){ setMsg('profMsg', firebaseError(error),'error'); } }

  function profileForAluno(aluno,normal=false){
    if(normal)return window.MaximusPedagogia.resolve({},'',ruleConfigCache);
    const extra=aluno?.id===alunoSelecionado?.id ? $('complementoProfessor')?.value : aluno?.complementoProfessor;
    const mode=document.querySelector('input[name="modoAdaptacao"]:checked')?.value||'auto';
    const manual=mode==='basica'?'Fonte ampliada; espaçamento ampliado':mode==='completa'?'Fonte ampliada; espaçamento ampliado; mais linhas; dica; linguagem simples':'';
    return window.MaximusPedagogia.resolve(aluno,[extra,manual].filter(Boolean).join('; '),ruleConfigCache);
  }
  function detectAdaptations(aluno){
    return [{id:'nome',title:'Identificação no modelo da escola',what:'Aluno, turma, disciplina, professor e data.'},...profileForAluno(aluno).rules,{id:'qr',title:'QR Code e data',what:'Registro da avaliação e da emissão. Sem diagnóstico no QR Code.'}];
  }

  function getModoAdaptacao(aluno){ const chosen=document.querySelector('input[name="modoAdaptacao"]:checked')?.value||'auto';return chosen==='completa'?'completa':'basica'; }

  function needsUpper(aluno){ return detectAdaptations(aluno).some(r=>r.id==='caixa-alta'); }
  function prefersMultiple(aluno){ const formato=$('formatoQuestoes')?.value; if(formato==='multipla') return true; if(formato==='discursiva') return false; return detectAdaptations(aluno).some(r=>r.id==='multipla'); }
  function renderActiveAdaptations(rules){ const box=$('adaptRulesBox'); if(!box)return;box.innerHTML=rules.map(r=>`<div class="card-mini active"><strong>${escapeHtml(r.title)}</strong>${r.status?`<span>${r.status==='arquivo'?'No documento':r.status==='em sala'?'Durante a aplicação':'Revisão do professor'}</span>`:''}<p>${escapeHtml(r.what||r.desc||'')}</p></div>`).join(''); }

  function pontuarItemBancoParaIa(item, disciplina, tema){
    const d=lower(disciplina), t=lower(tema);
    const itemDisc=lower(item.disciplina), itemTema=lower(item.tema);
    let score=0;
    if(d && itemDisc===d) score+=8;
    else if(d && itemDisc && (itemDisc.includes(d)||d.includes(itemDisc))) score+=4;
    t.split(/\s+/).filter(x=>x.length>3).forEach(x=>{ if(itemTema.includes(x)) score+=2; });
    if(t && itemTema===t) score+=8;
    return score;
  }

  function obterMaterialDoBancoParaIa(disciplina, tema){
    if(!$('usarBancoNaIa')?.checked || !bancoQuestoesCache.length) return '';
    const candidatos=bancoQuestoesCache.map(item=>({item,score:pontuarItemBancoParaIa(item,disciplina,tema)}))
      .filter(x=>x.score>0).sort((a,b)=>b.score-a.score).slice(0,8);
    return candidatos.map(({item})=>`EXERCÍCIOS DE REFERÊNCIA DO PROFESSOR\nDisciplina: ${item.disciplina||disciplina}\nTema: ${item.tema||tema}\n${editorContentToPlainText(item.conteudo||'').slice(0,3500)}`)
      .join('\n\n').slice(0,18000);
  }



  async function fillAutomaticQuestions(){
    if(!alunoSelecionado){ setMsg('profMsg','Selecione um aluno.','error'); return false; }

    const campoConteudo = $('conteudoMinistrado');
    const conteudoDigitado = norm(campoConteudo ? campoConteudo.value : '');

    if(!campoConteudo){
      setMsg('profMsg','Campo de conteúdo ministrado não encontrado na tela. Atualize esta versão do projeto.','error');
      return false;
    }

    if(conteudoDigitado.length < 25){
      campoConteudo.focus();
      setMsg('profMsg','Cole primeiro o conteúdo ministrado. A IA local do Ensino Médio gera as questões com base nesse texto.','error');
      return false;
    }

    const formato=norm($('formatoQuestoes')?.value || 'misto');
    const qtdObjetivas=formato==='misto'?Math.max(0,Math.min(25,parseInt($('qtdObjetivas')?.value||'0',10)||0)):(formato==='multipla'?Math.max(1,Math.min(25,parseInt($('qtdQuestoes')?.value||'6',10))):0);
    const qtdDiscursivas=formato==='misto'?Math.max(0,Math.min(25,parseInt($('qtdDiscursivas')?.value||'0',10)||0)):(formato==='discursiva'?Math.max(1,Math.min(25,parseInt($('qtdQuestoes')?.value||'6',10))):0);
    const qtd=Math.max(1,Math.min(25,qtdObjetivas+qtdDiscursivas));
    const disciplina=norm($('disciplina').value)||'disciplina';
    const tema=norm($('temaConteudo').value)||'conteúdo estudado';
    const materialBanco=obterMaterialDoBancoParaIa(disciplina,tema);
    const conteudo=[conteudoDigitado,materialBanco].filter(Boolean).join('\n\n');
    const dificuldade=norm($('dificuldade').value)||'Média';
    const modo=getModoAdaptacao(alunoSelecionado);
    const opts={qtd,qtdObjetivas,qtdDiscursivas,disciplina,tema,dificuldade,formato,modo,aluno:alunoSelecionado};
    if(qtdObjetivas+qtdDiscursivas<1)throw new Error('Escolha ao menos uma questão.');
    if(qtdObjetivas+qtdDiscursivas>25)throw new Error('Use no máximo 25 questões no total.');
    const questions=window.MaximusPedagogia.generateQuestions(conteudo,opts);
    const supportMode=$('modoTextoApoio')?.value||'auto',supportText=norm($('textoApoioGeral')?.value);
    const support=supportMode!=='nenhum'&&supportText?`<div class="support-text"><strong>Texto de apoio</strong><p>${escapeHtml(supportText)}</p></div>`:'';
    const htmlBonito=questions.map((q,i)=>`<article class="ai-question-card"><div class="ai-question-number">Questão ${i+1}</div><h3>${escapeHtml(q.title)}</h3>${support}${q.body.map(t=>`<p>${escapeHtml(t)}</p>`).join('')}${q.options.length?`<div class="options">${q.options.map(o=>`<p>${escapeHtml(o)}</p>`).join('')}</div>`:`<div class="answer-lines">${'<div></div>'.repeat(q.linhas)}</div>`}</article>`).join('');
    setEditorContent(htmlBonito);
    generatedAnswerKey=Object.fromEntries(questions.map((q,i)=>[i,q.answer]).filter(([,a])=>a!==null));
    answerKeyContent=getEditorContent();
    renderAnswerKeys();
    const origemBanco=materialBanco?' Também foi considerado o material compatível salvo no seu banco.':' Questões criadas a partir do texto fornecido.';
    setMsg('profMsg',`Gerador local criou ${qtd} questão(ões): ${qtdObjetivas} objetiva(s) e ${qtdDiscursivas} discursiva(s).${origemBanco} Revise antes de aplicar.`,'ok');
    return true;
  }

  async function gerarAutomatico(){
    const btn = $('gerarAutomatico');
    return withBusyState(btn,'IA local analisando o conteúdo...', async()=>{
      await wait(140);
      try { await fillAutomaticQuestions(); } catch(error) { setMsg('profMsg',firebaseError(error),'error'); }
    });
  }

  function renderGeneratedActivityHtml(text, info){
    const qs = parseQuestoes(text, info.modo || 'basica');
    const supportMode=$('modoTextoApoio')?.value||'auto';
    const supportText=norm($('textoApoioGeral')?.value||'');
    const header = `
      <section class="ai-generated-activity">
        <div class="ai-activity-cover">
          <span class="ai-label">Atividade</span>
          <h2>${escapeHtml(info.tema || 'Atividade')}</h2>
          <p><strong>Disciplina:</strong> ${escapeHtml(info.disciplina || '')}</p>
          <p><strong>Dificuldade:</strong> ${escapeHtml(info.dificuldade || '')} • <strong>Quantidade:</strong> ${escapeHtml(info.qtd || qs.length)}</p>
        </div>
    `;
    const cards = qs.map((q,idx)=>{
      const options = q.options?.length ? `<ol class="ai-options" type="A">${q.options.map(o=>`<li>${escapeHtml(String(o).replace(/^[A-E][).]\s*/i,''))}</li>`).join('')}</ol>` : '';
      const originalBody = q.body?.filter(x=>norm(x)).map(x=>`<p>${escapeHtml(x)}</p>`).join('') || '';
      const shouldSupport=supportMode==='todos'||(supportMode==='auto'&&originalBody);
      const supportContent=supportText||editorContentToPlainText(originalBody);
      const body = supportMode==='nenhum'?'':(shouldSupport&&supportContent?`<div class="support-text"><strong>Texto de apoio</strong><p>${escapeHtml(supportContent)}</p></div>`:originalBody);
      const hint = q.hint ? `<div class="ai-hint"><strong>Dica:</strong> ${escapeHtml(q.hint)}</div>` : '';
      const lines = Array.from({length:q.linhas||3},()=>'<div></div>').join('');
      return `
        <article class="ai-question-card">
          <div class="ai-question-number">Questão ${idx+1}</div>
          <h3>${escapeHtml(q.title || `Questão ${idx+1}`)}</h3>
          ${body}
          ${options}
          ${hint}
          <div class="answer-lines">${lines}</div>
        </article>
      `;
    }).join('');
    return `${header}${cards}</section>`;
  }

  function gerarQuestoesIA(conteudo, opts){
    const analise = analisarConteudoIAEnsinoMedio(conteudo, opts);
    const linhas=[];
    const total = Math.max(1, Math.min(25, opts.qtd || 6));
    const plano = planejarAvaliacaoEnsinoMedio(total, analise, opts);

    for(let i=1;i<=total;i++){
      const itemPlano = plano[i-1];
      const tipoMultipla = escolherTipoQuestaoEnsinoMedio(i, opts, analise);
      const q = montarQuestaoEnsinoMedio({
        i,
        tipoMultipla,
        perfil:itemPlano.perfil,
        habilidade:itemPlano.habilidade,
        topico:itemPlano.topico,
        analise,
        opts
      });

      linhas.push(`? ${q.title}`);
      if(q.body) linhas.push(q.body);
      if(q.options?.length) linhas.push(...q.options);
      if(q.hint) linhas.push(`@dica ${q.hint}`);
      linhas.push(`@linhas ${tipoMultipla ? 1 : (opts.modo==='completa'?5:(q.linhas || 3))}`);
      linhas.push('');
    }
    return linhas.join('\n');
  }

  function analisarConteudoIAEnsinoMedio(conteudo, opts){
    const bruto = limparTextoEnsinoMedio(conteudo);
    const secoes = extrairSecoesEstruturadasEnsinoMedio(bruto);
    const disciplina = classificarDisciplinaEnsinoMedio(`${opts.disciplina} ${opts.tema} ${bruto}`);
    const frases = extrairFrasesEnsinoMedio(bruto);
    const paragrafos = extrairParagrafosEnsinoMedio(bruto);
    const topicosManuais = extrairTopicosManuaisEnsinoMedio(bruto, secoes);
    const objetivosManuais = extrairObjetivosEnsinoMedio(bruto, secoes);
    const tokens = tokenizarEnsinoMedio(bruto);
    const freq = contarFrequenciasEnsinoMedio(tokens);
    const termos = selecionarTermosEnsinoMedio(freq, opts.tema, opts.disciplina);
    const ngrams = extrairNGramsEnsinoMedio(tokens);
    const definicoes = extrairDefinicoesEnsinoMedio(frases);
    const exemplos = extrairExemplosEnsinoMedio(frases);
    const datas = extrairDatasEnsinoMedio(bruto);
    const numeros = extrairNumerosEnsinoMedio(bruto);
    const formulas = extrairFormulasEnsinoMedio(bruto);
    const conceitos = combinarConceitosEnsinoMedio([...topicosManuais, ...termos], ngrams, definicoes, opts.tema, opts.disciplina);
    const topicosDetectados = detectarTopicosEnsinoMedio(`${opts.disciplina} ${opts.tema} ${bruto}`, disciplina);
    const topicos = enriquecerTopicosComEntradaManualEnsinoMedio(topicosDetectados, topicosManuais, disciplina);
    const frasesRelevantes = selecionarFrasesRelevantesEnsinoMedio(frases, conceitos, topicos);

    return {
      bruto, secoes, frases, paragrafos, topicosManuais, objetivosManuais, tokens, freq, termos, ngrams,
      definicoes, exemplos, datas, numeros, formulas, conceitos, topicos,
      disciplina,
      area:disciplina.area,
      resumo:frases.slice(0,4).join(' '),
      frasesRelevantes:frasesRelevantes.length ? frasesRelevantes : frases.slice(0,12),
      tema:norm(opts.tema) || conceitos[0] || disciplina.label || 'conteúdo estudado'
    };
  }

  function planejarAvaliacaoEnsinoMedio(total, analise, opts){
    const dificuldade = lower(opts.dificuldade || '');
    const baseFacil = [
      {perfil:'identificar', habilidade:'reconhecer conceitos centrais'},
      {perfil:'compreender', habilidade:'explicar ideias com clareza'},
      {perfil:'exemplificar', habilidade:'associar conceito e exemplo'}
    ];
    const baseMedia = [
      {perfil:'compreender', habilidade:'explicar relações entre conceitos'},
      {perfil:'aplicar', habilidade:'usar o conteúdo em situação-problema'},
      {perfil:'relacionar', habilidade:'relacionar teoria e prática'},
      {perfil:'analisar', habilidade:'analisar causa, consequência ou funcionamento'}
    ];
    const baseDificil = [
      {perfil:'analisar', habilidade:'analisar relações complexas'},
      {perfil:'comparar', habilidade:'comparar conceitos e contextos'},
      {perfil:'avaliar', habilidade:'avaliar argumentos e evidências'},
      {perfil:'resolver', habilidade:'resolver situação-problema'},
      {perfil:'sintetizar', habilidade:'produzir síntese crítica'}
    ];
    const matriz = dificuldade.includes('fácil') || dificuldade.includes('facil') ? baseFacil : (dificuldade.includes('dif') ? baseDificil : baseMedia);
    const topicos = analise.topicos.length ? analise.topicos : [{key:'geral', label:analise.tema, area:analise.area}];
    return Array.from({length:total}, (_,idx)=>({
      ...matriz[idx % matriz.length],
      topico:topicos[idx % topicos.length]
    }));
  }

  function escolherTipoQuestaoEnsinoMedio(i, opts, analise){
    const formato = lower(opts.formato || 'misto');
    if(formato.includes('multipla')) return true;
    if(formato.includes('discursiva')) return false;
    return i<=Math.max(1,parseInt(opts.qtdObjetivas||Math.ceil((opts.qtd||6)/2),10));
  }

  function montarQuestaoEnsinoMedio(ctx){
    const estruturada = montarQuestaoEstruturadaEntradaEnsinoMedio(ctx);
    if(estruturada) return estruturada;

    const especial = montarQuestaoTopicoEspecialEnsinoMedio(ctx);
    if(especial) return especial;

    const area = ctx.analise.disciplina.key;
    if(area==='matematica') return montarQuestaoMatematicaGeralEM(ctx);
    if(area==='portugues') return montarQuestaoPortuguesGeralEM(ctx);
    if(area==='redacao') return montarQuestaoRedacaoEM(ctx);
    if(area==='literatura') return montarQuestaoLiteraturaEM(ctx);
    if(area==='ingles') return montarQuestaoInglesEM(ctx);
    if(area==='fisica') return montarQuestaoFisicaGeralEM(ctx);
    if(area==='quimica') return montarQuestaoQuimicaGeralEM(ctx);
    if(area==='biologia') return montarQuestaoBiologiaGeralEM(ctx);
    if(area==='historia') return montarQuestaoHistoriaEM(ctx);
    if(area==='geografia') return montarQuestaoGeografiaEM(ctx);
    if(area==='filosofia') return montarQuestaoFilosofiaEM(ctx);
    if(area==='sociologia') return montarQuestaoSociologiaEM(ctx);
    if(area==='artes') return montarQuestaoArtesEM(ctx);
    if(area==='educacao_fisica') return montarQuestaoEducacaoFisicaEM(ctx);
    if(area==='tecnologia') return montarQuestaoTecnologiaEM(ctx);
    return montarQuestaoGeralEM(ctx);
  }

  function montarQuestaoEstruturadaEntradaEnsinoMedio(ctx){
    const a = ctx.analise;

    if(a.objetivosManuais?.length && ctx.i % 5 === 0){
      const obj = a.objetivosManuais[(ctx.i-1) % a.objetivosManuais.length];
      if(ctx.tipoMultipla){
        return {
          title:`Qual alternativa está mais relacionada ao objetivo da aula: "${encurtarEM(obj,110)}"?`,
          body:'',
          options:renumerarAlternativasEM(embaralharEM([
            `A) Compreender e aplicar o objetivo indicado no conteúdo da aula.`,
            `B) Ignorar o conteúdo e responder apenas por opinião pessoal.`,
            `C) Memorizar uma palavra isolada sem entender o contexto.`,
            `D) Escolher uma alternativa sem relação com o tema estudado.`
          ], ctx.i)),
          hint:'Observe o objetivo indicado pelo professor no conteúdo colado.',
          linhas:1
        };
      }
      return {
        title:`Explique como o objetivo da aula se relaciona ao conteúdo estudado: "${encurtarEM(obj,140)}".`,
        body:'Use exemplos, conceitos ou tópicos trabalhados em sala.',
        options:null,
        hint:'Retome o objetivo e conecte com pelo menos um conceito do conteúdo.',
        linhas:4
      };
    }

    if(a.formulas?.length && ctx.i % 4 === 0){
      const formula = a.formulas[(ctx.i-1) % a.formulas.length];
      if(ctx.tipoMultipla){
        return {
          title:`No conteúdo estudado, qual é a função da fórmula ou relação "${formula}"?`,
          body:'Analise a fórmula dentro do tema da aula.',
          options:renumerarAlternativasEM(embaralharEM([
            `A) Representar uma relação entre grandezas ou variáveis do conteúdo.`,
            `B) Substituir a leitura do enunciado por uma resposta aleatória.`,
            `C) Indicar uma informação sem relação com cálculos ou interpretação.`,
            `D) Mostrar apenas uma palavra decorativa do material.`
          ], ctx.i)),
          hint:'Identifique as grandezas ou termos presentes na fórmula.',
          linhas:1
        };
      }
      return {
        title:`Explique a fórmula/relação "${formula}" e indique o que ela permite calcular ou interpretar.`,
        body:'Use o conteúdo ministrado para descrever as grandezas envolvidas.',
        options:null,
        hint:'Diga o que cada parte representa e quando a fórmula pode ser usada.',
        linhas:4
      };
    }

    if(a.datas?.length && (a.disciplina.key==='historia' || a.disciplina.key==='geografia') && ctx.i % 4 === 0){
      const data = a.datas[(ctx.i-1) % a.datas.length];
      return {
        title: ctx.tipoMultipla ? `Qual alternativa melhor contextualiza a data/período "${data}" no conteúdo estudado?` : `Contextualize a data/período "${data}" dentro do conteúdo estudado.`,
        body:'Relacione tempo histórico, espaço e consequências.',
        options: ctx.tipoMultipla ? renumerarAlternativasEM(embaralharEM([
          `A) Deve ser relacionada ao contexto, aos sujeitos envolvidos e às consequências do processo estudado.`,
          `B) É apenas um número sem relação com tempo histórico ou espaço geográfico.`,
          `C) Elimina a necessidade de compreender causas e consequências.`,
          `D) Serve somente para decorar, sem interpretar o conteúdo.`
        ], ctx.i)) : null,
        hint:'Localize o período no contexto e relacione com causas ou efeitos.',
        linhas: ctx.tipoMultipla ? 1 : 4
      };
    }

    return null;
  }

  function montarQuestaoTopicoEspecialEnsinoMedio(ctx){
    const key = ctx.topico?.key || '';
    if(key==='fracao') return montarQuestaoFracaoEM(ctx);
    if(key==='porcentagem') return montarQuestaoPorcentagemEM(ctx);
    if(key==='funcao') return montarQuestaoFuncaoEM(ctx);
    if(key==='equacao') return montarQuestaoEquacaoEM(ctx);
    if(key==='geometria') return montarQuestaoGeometriaEM(ctx);
    if(key==='estatistica') return montarQuestaoEstatisticaEM(ctx);
    if(key==='trigonometria') return montarQuestaoTrigonometriaEM(ctx);
    if(key==='crase') return montarQuestaoCraseEM(ctx);
    if(key==='interpretacao') return montarQuestaoInterpretacaoEM(ctx);
    if(key==='redacao_argumentativa') return montarQuestaoRedacaoEM(ctx);
    if(key==='literatura') return montarQuestaoLiteraturaEM(ctx);
    if(key==='cinematica' || key==='dinamica' || key==='energia' || key==='eletricidade' || key==='ondas' || key==='optica') return montarQuestaoFisicaTopicoEM(ctx);
    if(key==='atomistica' || key==='ligacoes_quimicas' || key==='estequiometria' || key==='solucoes_ph' || key==='quimica_organica' || key==='termoquimica' || key==='equilibrio_quimico') return montarQuestaoQuimicaTopicoEM(ctx);
    if(key==='celula' || key==='genetica' || key==='ecologia' || key==='evolucao' || key==='fisiologia') return montarQuestaoBiologiaTopicoEM(ctx);
    if(key==='brasil_colonia' || key==='revolucoes' || key==='guerras' || key==='democracia' || key==='historia_brasil') return montarQuestaoHistoriaEM(ctx);
    if(key==='clima' || key==='cartografia' || key==='urbanizacao' || key==='globalizacao' || key==='meio_ambiente') return montarQuestaoGeografiaEM(ctx);
    if(key==='etica' || key==='conhecimento' || key==='politica_filosofia') return montarQuestaoFilosofiaEM(ctx);
    if(key==='cultura' || key==='desigualdade' || key==='trabalho_sociedade') return montarQuestaoSociologiaEM(ctx);
    if(key==='english_grammar' || key==='english_reading') return montarQuestaoInglesEM(ctx);
    return null;
  }

  function limparTextoEnsinoMedio(texto){
    return norm(texto)
      .replace(/[•●▪▫]/g,' ')
      .replace(/\t/g,' ')
      .replace(/[“”]/g,'"')
      .replace(/[‘’]/g,"'")
      .replace(/\s+\n/g,'\n')
      .replace(/\n\s+/g,'\n')
      .replace(/[ ]{2,}/g,' ')
      .trim();
  }

  function extrairFrasesEnsinoMedio(texto){
    const partes = texto
      .replace(/\s+/g,' ')
      .split(/(?<=[.!?])\s+|;\s+|\n+/)
      .map(s=>s.trim())
      .filter(s=>s.length>=16 && s.length<=520);
    return partes.length ? partes.slice(0,90) : [texto.slice(0,380)];
  }

  function extrairParagrafosEnsinoMedio(texto){
    return texto.split(/\n{2,}|\r{2,}/).map(s=>s.trim()).filter(s=>s.length>35).slice(0,20);
  }


  function extrairSecoesEstruturadasEnsinoMedio(texto){
    const secoes = {};
    let atual = 'geral';
    String(texto||'').split(/\r?\n/).forEach(linhaRaw=>{
      const linha = linhaRaw.trim();
      if(!linha) return;
      const m = linha.match(/^(tema|assunto|conte[uú]do|t[oó]picos?|habilidades?|objetivos?|exemplos?|f[oó]rmulas?|dados importantes|palavras-chave)\s*:\s*(.*)$/i);
      if(m){
        atual = lower(m[1]).normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\s+/g,'_');
        if(!secoes[atual]) secoes[atual]=[];
        if(m[2]) secoes[atual].push(m[2].trim());
      }else{
        if(!secoes[atual]) secoes[atual]=[];
        secoes[atual].push(linha.replace(/^[-*•\d.)]+\s*/,'').trim());
      }
    });
    return secoes;
  }

  function extrairTopicosManuaisEnsinoMedio(texto, secoes={}){
    const topicos = [];
    ['topicos','topico','conteudos','conteudo','habilidades','habilidade','palavras-chave','palavras_chave','formulas','formula','dados_importantes'].forEach(k=>{
      (secoes[k]||[]).forEach(v=>topicos.push(v));
    });

    const linhas = String(texto||'').split(/\r?\n/).map(l=>l.trim()).filter(Boolean);
    let capturar = false;
    linhas.forEach(linha=>{
      if(/^(tema|assunto|conte[uú]do)\s*:/i.test(linha)){
        const apos = linha.split(':').slice(1).join(':').trim();
        if(apos && apos.length>=3) topicos.unshift(apos);
        return;
      }
      if(/^(t[oó]picos?|conte[uú]dos?|habilidades?|objetivos?|exemplos?|f[oó]rmulas?|dados importantes)\s*:/i.test(linha)){
        capturar = true;
        const apos = linha.split(':').slice(1).join(':').trim();
        if(apos && apos.length>=3) topicos.push(...apos.split(/[,;]+/).map(x=>x.trim()));
        return;
      }
      if(/^[-*•\d.)]+\s*/.test(linha)){
        const item = linha.replace(/^[-*•\d.)]+\s*/, '').trim();
        if(item.length>=3) topicos.push(item);
        return;
      }
      if(capturar && linha.length>=3 && linha.length<150){
        topicos.push(linha);
      }
    });

    return [...new Set(topicos.map(t=>t.replace(/\s+/g,' ').trim()).filter(t=>t.length>=3 && t.length<=140))].slice(0,40);
  }

  function extrairObjetivosEnsinoMedio(texto, secoes={}){
    const objetivos = [];
    ['objetivo','objetivos','habilidade','habilidades'].forEach(k=>(secoes[k]||[]).forEach(v=>objetivos.push(v)));
    String(texto||'').split(/\r?\n/).forEach(linha=>{
      if(/objetiv|habilidade|compet[eê]ncia|descritor|enem|bncc/i.test(linha)){
        const item = linha.replace(/^(objetivos?|habilidades?|compet[eê]ncias?|descritores?)\s*:\s*/i,'').replace(/^[-*•\d.)]+\s*/,'').trim();
        if(item.length>4) objetivos.push(item);
      }
    });
    return [...new Set(objetivos.map(o=>o.replace(/\s+/g,' ').trim()).filter(o=>o.length>=4 && o.length<=180))].slice(0,16);
  }

  function enriquecerTopicosComEntradaManualEnsinoMedio(topicosDetectados, topicosManuais, disciplina){
    const topicos = [...topicosDetectados];
    const usados = new Set(topicos.map(t=>lower(t.label)));
    topicosManuais.slice(0,10).forEach((t,idx)=>{
      const label = t.replace(/\s+/g,' ').trim();
      if(label.length<3 || usados.has(lower(label))) return;
      topicos.push({key:`manual_${idx+1}`, label, area:disciplina.key, manual:true});
      usados.add(lower(label));
    });
    return topicos.slice(0,14);
  }

  function tokenizarEnsinoMedio(texto){
    return lower(texto)
      .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
      .replace(/[^a-z0-9\s/%²³+-]/g,' ')
      .split(/\s+/)
      .map(t=>t.trim())
      .filter(Boolean);
  }

  function stopwordsEnsinoMedio(){
    return new Set('a o as os um uma uns umas de da do das dos e em no na nos nas para por com sem que se ao aos onde como mais menos muito muita muitos muitas esse essa isso isto aquele aquela aqueles aquelas quando porque pois sobre entre tambem seu sua seus suas foi sao ser ter tem ha ja ou cada qual quais pode podem deve devem professor aluno aula conteudo atividade prova questao questoes exercicio exemplo exemplos texto forma parte partes usado usados estudar estudado explica explicacao conceito conceitos principais principal importante importantes acordo abaixo acima assim ainda antes depois durante dentro fora todos todas todo toda item alternativa resposta responda assinale leia observe'.split(' '));
  }

  function contarFrequenciasEnsinoMedio(tokens){
    const stop = stopwordsEnsinoMedio();
    const freq = {};
    tokens.forEach(t=>{
      if(t.length<4 || stop.has(t)) return;
      freq[t]=(freq[t]||0)+1;
    });
    return freq;
  }

  function selecionarTermosEnsinoMedio(freq, tema, disciplina){
    const extras = tokenizarEnsinoMedio(`${tema} ${disciplina}`).filter(t=>t.length>3);
    const lista = Object.entries(freq).sort((a,b)=>b[1]-a[1]).map(([k])=>k);
    return [...new Set([...extras, ...lista])].slice(0,36);
  }

  function extrairNGramsEnsinoMedio(tokens){
    const stop = stopwordsEnsinoMedio();
    const grams = {};
    for(let n=2;n<=4;n++){
      for(let i=0;i<=tokens.length-n;i++){
        const parts = tokens.slice(i,i+n);
        if(parts.some(p=>p.length<3 || stop.has(p))) continue;
        const gram = parts.join(' ');
        grams[gram]=(grams[gram]||0)+1;
      }
    }
    return Object.entries(grams)
      .filter(([,v])=>v>1)
      .sort((a,b)=>b[1]-a[1])
      .slice(0,18)
      .map(([k])=>k);
  }

  function extrairDefinicoesEnsinoMedio(frases){
    const defs=[];
    frases.forEach(frase=>{
      const clean=frase.trim();
      const patterns=[
        /^(.{3,95}?)\s+(é|são|representa|representam|significa|significam|consiste|corresponde|refere-se|define-se)\s+(.{8,300})/i,
        /^(.{3,95}?)\s+(possui|possuem|apresenta|apresentam|tem|têm|envolve|envolvem)\s+(.{8,300})/i,
        /(.{3,95}?)\s*:\s*(.{8,300})/i
      ];
      for(const p of patterns){
        const m=clean.match(p);
        if(m){
          defs.push({
            termo:norm(m[1]).replace(/^[,.:\s]+|[,.:\s]+$/g,''),
            definicao:norm(m[3] || m[2])
          });
          break;
        }
      }
    });
    return defs.filter(d=>d.termo.length>=3 && d.termo.length<=95).slice(0,18);
  }

  function extrairExemplosEnsinoMedio(frases){
    return frases.filter(f=>/exemplo|por exemplo|como em|como no|como na|situa[cç][aã]o|cotidiano|dia a dia|aplica[cç][aã]o|caso|experimento|observe/i.test(f)).slice(0,16);
  }

  function extrairDatasEnsinoMedio(texto){
    return [...texto.matchAll(/\b(?:\d{1,2}\/\d{1,2}\/\d{2,4}|\d{4}|século\s+[ivxlcdm]+|s[eé]culo\s+\d+)\b/gi)].map(m=>m[0]).slice(0,16);
  }

  function extrairNumerosEnsinoMedio(texto){
    const fracoes = [...texto.matchAll(/\b\d+\s*\/\s*\d+\b/g)].map(m=>m[0].replace(/\s+/g,''));
    const porcentagens = [...texto.matchAll(/\b\d+(?:[,.]\d+)?\s*%/g)].map(m=>m[0]);
    const numeros = [...texto.matchAll(/\b\d+(?:[,.]\d+)?\b/g)].map(m=>m[0]);
    return {fracoes:[...new Set(fracoes)].slice(0,16), porcentagens:[...new Set(porcentagens)].slice(0,16), numeros:[...new Set(numeros)].slice(0,20)};
  }

  function extrairFormulasEnsinoMedio(texto){
    const formulas = [];
    const patterns = [
      /[a-zA-Z]\s*=\s*[^.;,\n]{1,50}/g,
      /\b(?:F\s*=\s*m\.?a|E\s*=\s*m\.?c|v\s*=\s*Δ?s\/Δ?t|pH\s*=\s*-?log|PV\s*=\s*nRT|U\s*=\s*R\.?i)\b/gi,
      /\b[A-Z][a-z]?\d*(?:[A-Z][a-z]?\d*)+\b/g
    ];
    patterns.forEach(p=>{
      [...texto.matchAll(p)].forEach(m=>formulas.push(norm(m[0])));
    });
    return [...new Set(formulas)].slice(0,18);
  }

  function combinarConceitosEnsinoMedio(termos, ngrams, definicoes, tema, disciplina){
    const defs = definicoes.map(d=>d.termo).filter(t=>t.length<=80);
    const base = [...tokenizarEnsinoMedio(`${tema} ${disciplina}`).filter(t=>t.length>3), ...defs, ...ngrams, ...termos];
    return [...new Set(base.map(t=>String(t).replace(/\s+/g,' ').trim()).filter(t=>t.length>=4 && t.length<=80))].slice(0,36);
  }

  function selecionarFrasesRelevantesEnsinoMedio(frases, conceitos, topicos){
    const c = [...conceitos, ...topicos.map(t=>t.label)].map(x=>lower(x));
    return frases
      .map(f=>({f, score:c.reduce((s,k)=>s+(k && lower(f).includes(k)?2:0),0) + Math.min(f.length/100,3)}))
      .sort((a,b)=>b.score-a.score)
      .map(x=>x.f)
      .slice(0,24);
  }

