  async function editProfessor(event){
    event.preventDefault();const id=editingProfessorId,name=norm($('editarProfNome').value),selected=[...$('editarProfTurmas').querySelectorAll('input:checked')].map(input=>input.value);
    const ok=await runManagementChange(event.submitter,'editarProfMsg','Salvando professor...',async()=>{
      const data=await managementSnapshot(),profile=data.teachers.find(p=>p.id===id);if(!profile||profile.ativo===false)throw new Error('O professor já foi removido.');
      const classes=activeClassList(data.registry,data.students,data.teachers),turmas=selected.map(key=>classes.find(t=>t.key===key)?.nome);if(turmas.some(t=>!t))throw new Error('Uma turma selecionada foi removida. Abra o cadastro novamente.');
      if(!name)throw new Error('Informe o nome do professor.');await sendManagementUpdates({['usuarios/'+id+'/nome']:name,['usuarios/'+id+'/turmas']:turmas,['usuarios/'+id+'/turmasAcesso']:Object.fromEntries(turmas.map(t=>[C.classKey(t),true]))});
    });if(ok){$('editarProfessorDialog').close();setMsg('professorMsg','Professor atualizado.','ok');}
  }
  async function createManagedAccount({role,nome,email,password,turmas=[]}){
    requireCoordinator();if(accountCreationInFlight)throw new Error('Aguarde o cadastro em andamento.');
    if(!nome||nome.length>100)throw new Error('Informe um nome com até 100 caracteres.');
    accountCreationInFlight=true;const owner=currentUser.uid;let secondary,createdUser,createdFresh=false,profileSaved=false;
    try{
      secondary=await getSecondaryAuth();if(secondary.setPersistence&&firebase.auth.Auth?.Persistence?.NONE)await secondary.setPersistence(firebase.auth.Auth.Persistence.NONE);
      try{const credential=await secondary.createUserWithEmailAndPassword(email,password);createdUser=credential.user;createdFresh=true;}
      catch(error){if(error.code!=='auth/email-already-in-use')throw error;const credential=await secondary.signInWithEmailAndPassword(email,password);createdUser=credential.user;const existing=(await db.ref('usuarios/'+createdUser.uid).once('value')).val();if(existing)throw error;}
      requireCoordinator();if(currentUser.uid!==owner)throw new Error('O acesso mudou. Entre novamente.');
      const profile={role,nome,email,ativo:true,mustChangePassword:true,criadoEm:nowIso()},updates={};
      if(role==='professor'){profile.turmas=turmas;profile.turmasAcesso=Object.fromEntries(turmas.map(t=>[C.classKey(t),true]));appendClassRegistration(updates,turmas);}
      updates['usuarios/'+createdUser.uid]=profile;await sendManagementUpdates(updates);profileSaved=true;await audit('cadastro_'+role,{uid:createdUser.uid,email});return createdUser.uid;
    }catch(error){
      if(createdFresh&&createdUser&&!profileSaved){try{await createdUser.delete();}catch{}}
      throw error;
    }finally{try{await secondary?.signOut();}catch{}accountCreationInFlight=false;}
  }
  async function cadastrarProfessor(event){
    event.preventDefault();const button=event.submitter||$('professorForm').querySelector('[type=submit]');
    const ok=await runManagementChange(button,'professorMsg','Cadastrando professor...',async()=>{
      const turmas=[...new Map([...$('turmasCheckboxes').querySelectorAll('input:checked')].map(i=>i.value).concat(splitTurmas($('cadProfTurmasExtras').value)).map(t=>[C.classKey(t),norm(t)])).values()];
      if(!turmas.length)throw new Error('Selecione ou digite pelo menos uma turma.');
      await createManagedAccount({role:'professor',nome:norm($('cadProfNome').value),email:norm($('cadProfEmail').value),password:requireSamePassword('cadProfSenha','cadProfConfirmaSenha'),turmas});
    });if(ok){$('professorForm').reset();setMsg('professorMsg','Professor cadastrado.','ok');}
  }
